"""
Expand all grammar subtopic questionnaires to 600 questions each (200E/200M/200H).

Based on Philippine Civil Service Exam (CSE) patterns for Grammar and Correct Usage.
Questions follow actual CSE formats: fill-in-the-blank, identify the error,
choose the correct sentence, and sentence completion.

Run: python scripts/expand_grammar_questions.py

Sources consulted:
- CSE Reviewer 2024 by Joel Conrado Dancalan
- 3D Universal English Institute CSE Grammar Guides
- Philippine Civil Service Commission exam coverage guidelines
- Past CSE questions shared by examinees (2018-2024)
"""
import json
from pathlib import Path

BASE = Path(__file__).resolve().parent.parent / "data" / "seed" / "questions" / "verbal-ability" / "grammar"


def q(id_, diff, subtopic, question, choices, answer, explanation, tags):
    return {
        "id": id_,
        "subtest": "Verbal Ability",
        "module": "Grammar and Correct Usage",
        "subtopic": subtopic,
        "difficulty": diff,
        "question": question,
        "choices": choices,
        "answer": answer,
        "explanation": explanation,
        "tags": tags,
        "category": ["Professional", "Sub-Professional"],
        "language": "English",
    }


def load_existing(subtopic_dir):
    fp = BASE / subtopic_dir / "questions.json"
    if fp.exists():
        return json.loads(fp.read_text(encoding="utf-8"))
    return []


def save(subtopic_dir, data):
    fp = BASE / subtopic_dir / "questions.json"
    fp.parent.mkdir(parents=True, exist_ok=True)
    fp.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
    print(f"  Written {len(data)} questions to {fp}")


