# PREPOSITIONS — needs +100 Hard
# ============================================================
def gen_prepositions():
    """Generate 100 additional Hard questions for Prepositions."""
    existing = load_existing("prepositions")
    start_id = max(item["id"] for item in existing) + 1
    new = []
    st = "Prepositions"

    hard_questions = [
        ("The committee agreed ___ the proposal after a lengthy deliberation.", ["with","to","on","upon"], "to", "'Agree to' a proposal/plan/suggestion. 'Agree with' a person. 'Agree on' a point/issue.", ["agree to","proposal"]),
        ("The director is not amenable ___ the idea of extending the deadline.", ["with","to","for","on"], "to", "'Amenable to' means open/receptive to something.", ["amenable to","adjective + preposition"]),
        ("The new policy is tantamount ___ an admission of failure.", ["with","to","as","for"], "to", "'Tantamount to' means equivalent to.", ["tantamount to","fixed expression"]),
        ("The employee was charged ___ neglect of duty.", ["for","with","of","about"], "with", "'Charged with' an offense/crime. 'Charged for' a fee.", ["charged with","legal context"]),
        ("The supervisor is averse ___ making hasty decisions without consulting the team.", ["with","to","from","for"], "to", "'Averse to' means opposed to or reluctant about.", ["averse to","adjective + preposition"]),
        ("The memorandum is replete ___ grammatical errors that need to be corrected.", ["of","with","in","by"], "with", "'Replete with' means full of or abundantly supplied with.", ["replete with","adjective + preposition"]),
        ("The findings are consistent ___ the initial assessment made by the audit team.", ["to","with","in","for"], "with", "'Consistent with' means in agreement with.", ["consistent with","adjective + preposition"]),
        ("The employee was absolved ___ all charges after the investigation.", ["from","of","with","for"], "of", "'Absolved of' charges/blame/responsibility.", ["absolved of","legal context"]),
        ("The regulation is incumbent ___ all government employees regardless of rank.", ["to","upon","for","with"], "upon", "'Incumbent upon/on' means obligatory for.", ["incumbent upon","formal expression"]),
        ("The decision is contingent ___ the availability of funds.", ["to","upon","with","for"], "upon", "'Contingent upon/on' means dependent on.", ["contingent upon","formal expression"]),
    ]

    hard_questions += [
        ("The officer was remiss ___ his duties during the critical period.", ["of","in","with","about"], "in", "'Remiss in' one's duties/responsibilities.", ["remiss in","adjective + preposition"]),
        ("The department head takes pride ___ the accomplishments of her team.", ["of","in","with","for"], "in", "'Take pride in' something (not 'of').", ["take pride in","idiomatic expression"]),
        ("The applicant was disqualified ___ the examination for submitting fraudulent documents.", ["in","from","of","to"], "from", "'Disqualified from' an activity/competition/examination.", ["disqualified from","verb + preposition"]),
        ("The new employee is oblivious ___ the office protocols that have been in place for years.", ["about","to","of","with"], "to", "'Oblivious to/of' means unaware of. 'To' is more common in modern usage.", ["oblivious to","adjective + preposition"]),
        ("The committee's decision is predicated ___ the assumption that all data submitted are accurate.", ["in","on","to","with"], "on", "'Predicated on/upon' means based on.", ["predicated on","formal expression"]),
        ("The supervisor prevailed ___ the employee to reconsider his resignation.", ["on","upon","over","with"], "upon", "'Prevail upon/on' someone means to persuade them.", ["prevail upon","verb + preposition"]),
        ("The government agency prides itself ___ its efficient delivery of public services.", ["in","on","with","for"], "on", "'Pride oneself on' something.", ["pride oneself on","reflexive + preposition"]),
        ("The employee was admonished ___ his repeated tardiness.", ["about","for","of","with"], "for", "'Admonished for' a fault/offense.", ["admonished for","verb + preposition"]),
        ("The regulation militated ___ the approval of the request.", ["for","against","to","with"], "against", "'Militate against' means to work against or make less likely.", ["militate against","formal verb"]),
        ("The director acquiesced ___ the demands of the union after prolonged negotiations.", ["with","to","in","on"], "in", "'Acquiesce in/to' means to accept reluctantly. 'In' is more formal/traditional.", ["acquiesce in","formal verb"]),
    ]

    hard_questions += [
        ("The findings are at variance ___ the conclusions stated in the previous report.", ["to","with","from","against"], "with", "'At variance with' means in disagreement with.", ["at variance with","fixed expression"]),
        ("The employee has an aversion ___ public speaking.", ["for","to","of","with"], "to", "'Aversion to' something one dislikes.", ["aversion to","noun + preposition"]),
        ("The committee deliberated ___ the matter for three hours before reaching a consensus.", ["about","on","over","upon"], "on", "'Deliberate on/upon' a matter (formal). 'About' is also acceptable but less formal.", ["deliberate on","formal usage"]),
        ("The supervisor is conversant ___ the new regulations governing overtime pay.", ["about","with","in","of"], "with", "'Conversant with' means familiar with or knowledgeable about.", ["conversant with","adjective + preposition"]),
        ("The employee was prevailed ___ to withdraw his complaint.", ["on","upon","over","with"], "upon", "'Prevailed upon' means persuaded.", ["prevailed upon","passive + preposition"]),
        ("The new policy is inimical ___ the interests of rank-and-file employees.", ["for","to","with","against"], "to", "'Inimical to' means harmful or hostile to.", ["inimical to","adjective + preposition"]),
        ("The director took umbrage ___ the employee's insinuation of favoritism.", ["with","at","to","for"], "at", "'Take umbrage at' means to feel offended by.", ["take umbrage at","idiomatic expression"]),
        ("The committee arrived ___ a decision after considering all the evidence.", ["to","at","on","in"], "at", "'Arrive at' a decision/conclusion/agreement.", ["arrive at","verb + preposition"]),
        ("The employee was exonerated ___ the charges of misconduct.", ["from","of","with","for"], "of", "'Exonerated of/from' charges. Both are acceptable; 'of' is more common.", ["exonerated of","legal context"]),
        ("The regulation is binding ___ all employees of the agency.", ["to","on","for","with"], "on", "'Binding on/upon' means obligatory for.", ["binding on","adjective + preposition"]),
    ]

    hard_questions += [
        ("The supervisor is impervious ___ criticism from subordinates.", ["from","to","of","against"], "to", "'Impervious to' means unaffected by.", ["impervious to","adjective + preposition"]),
        ("The employee was bereft ___ any support from his colleagues during the hearing.", ["from","of","with","by"], "of", "'Bereft of' means deprived of or lacking.", ["bereft of","adjective + preposition"]),
        ("The new system is conducive ___ greater efficiency in processing applications.", ["for","to","of","with"], "to", "'Conducive to' means favorable to or promoting.", ["conducive to","adjective + preposition"]),
        ("The director is disposed ___ granting the request provided all requirements are met.", ["for","to","of","with"], "to", "'Disposed to' means inclined or willing to.", ["disposed to","adjective + preposition"]),
        ("The committee took exception ___ the manner in which the investigation was conducted.", ["with","to","at","for"], "to", "'Take exception to' means to object to.", ["take exception to","idiomatic expression"]),
        ("The employee is liable ___ disciplinary action for his repeated violations.", ["for","to","of","with"], "to", "'Liable to' a penalty/action. 'Liable for' damages/costs.", ["liable to","legal context"]),
        ("The regulation is applicable ___ all government employees without exception.", ["for","to","on","with"], "to", "'Applicable to' means relevant to or affecting.", ["applicable to","adjective + preposition"]),
        ("The supervisor is partial ___ employees who arrive early.", ["for","to","with","of"], "to", "'Partial to' means having a preference for.", ["partial to","adjective + preposition"]),
        ("The committee is seized ___ the matter and will render a decision within thirty days.", ["with","of","by","on"], "of", "'Seized of' a matter (legal) means having jurisdiction over or being aware of.", ["seized of","legal expression"]),
        ("The employee was divested ___ his authority pending the investigation.", ["from","of","with","by"], "of", "'Divested of' means stripped of or deprived of.", ["divested of","formal verb"]),
    ]

    hard_questions += [
        ("The findings are indicative ___ a systemic problem within the organization.", ["for","of","to","about"], "of", "'Indicative of' means suggesting or pointing to.", ["indicative of","adjective + preposition"]),
        ("The director is amenable ___ suggestions from the rank and file.", ["for","to","with","of"], "to", "'Amenable to' means receptive to.", ["amenable to","adjective + preposition"]),
        ("The employee was enjoined ___ disclosing confidential information.", ["against","from","to","of"], "from", "'Enjoined from' means prohibited from (legal).", ["enjoined from","legal context"]),
        ("The regulation is predicated ___ the principle of accountability in public service.", ["in","on","to","with"], "on", "'Predicated on/upon' means based on or founded on.", ["predicated on","formal expression"]),
        ("The committee is cognizant ___ the difficulties faced by field employees.", ["about","of","with","to"], "of", "'Cognizant of' means aware of.", ["cognizant of","adjective + preposition"]),
        ("The supervisor was negligent ___ performing his supervisory functions.", ["of","in","about","for"], "in", "'Negligent in' performing duties.", ["negligent in","adjective + preposition"]),
        ("The employee was derelict ___ his duty when he failed to report the irregularity.", ["of","in","from","with"], "in", "'Derelict in' one's duty means failing to fulfill obligations.", ["derelict in","adjective + preposition"]),
        ("The new policy redounds ___ the benefit of all government employees.", ["for","to","in","with"], "to", "'Redound to' the benefit/credit/advantage of someone.", ["redound to","formal verb"]),
        ("The committee is tasked ___ reviewing all pending applications.", ["for","with","to","in"], "with", "'Tasked with' means assigned the responsibility of.", ["tasked with","verb + preposition"]),
        ("The employee was made to account ___ the missing funds.", ["about","for","of","to"], "for", "'Account for' means to explain or answer for.", ["account for","phrasal verb"]),
    ]

    hard_questions += [
        ("The regulation is commensurate ___ the gravity of the offense committed.", ["to","with","for","in"], "with", "'Commensurate with' means proportionate to.", ["commensurate with","adjective + preposition"]),
        ("The director is intent ___ implementing reforms despite opposition.", ["in","on","to","for"], "on", "'Intent on' means determined to.", ["intent on","adjective + preposition"]),
        ("The employee was oblivious ___ the consequences of his actions.", ["about","to","of","with"], "to", "'Oblivious to' means unaware of.", ["oblivious to","adjective + preposition"]),
        ("The committee is comprised ___ representatives from all regional offices.", ["with","of","by","from"], "of", "'Comprised of' (though debated, widely used) means composed of.", ["comprised of","composition"]),
        ("The supervisor is answerable ___ the director for the performance of his division.", ["for","to","with","before"], "to", "'Answerable to' a person (authority). 'Answerable for' an action/result.", ["answerable to","adjective + preposition"]),
        ("The employee was confronted ___ evidence of his involvement in the anomaly.", ["by","with","of","about"], "with", "'Confronted with' evidence/facts/problems.", ["confronted with","verb + preposition"]),
        ("The regulation is tantamount ___ a prohibition on overtime work.", ["as","to","with","for"], "to", "'Tantamount to' means equivalent to.", ["tantamount to","adjective + preposition"]),
        ("The committee dispensed ___ the formalities and proceeded directly to the main agenda.", ["of","with","from","about"], "with", "'Dispense with' means to do without or skip.", ["dispense with","phrasal verb"]),
        ("The employee was imbued ___ a strong sense of public service.", ["by","with","of","in"], "with", "'Imbued with' means filled with or inspired by.", ["imbued with","adjective + preposition"]),
        ("The director is predisposed ___ approving requests that are well-documented.", ["for","to","in","with"], "to", "'Predisposed to' means inclined toward.", ["predisposed to","adjective + preposition"]),
    ]

    hard_questions += [
        ("The findings are symptomatic ___ deeper organizational problems.", ["for","of","to","with"], "of", "'Symptomatic of' means indicative of or characteristic of.", ["symptomatic of","adjective + preposition"]),
        ("The employee was precluded ___ participating in the bidding process.", ["to","from","of","against"], "from", "'Precluded from' means prevented from.", ["precluded from","verb + preposition"]),
        ("The regulation is subservient ___ the provisions of the Constitution.", ["with","to","for","under"], "to", "'Subservient to' means subordinate to.", ["subservient to","adjective + preposition"]),
        ("The committee is vested ___ the authority to impose sanctions.", ["by","with","of","in"], "with", "'Vested with' authority/power means given or endowed with.", ["vested with","legal expression"]),
        ("The supervisor was remonstrated ___ for his harsh treatment of subordinates.", ["about","with","against","for"], "with", "'Remonstrate with' someone means to protest to them.", ["remonstrate with","formal verb"]),
        ("The employee is susceptible ___ flattery and may be easily manipulated.", ["for","to","of","with"], "to", "'Susceptible to' means vulnerable to or easily affected by.", ["susceptible to","adjective + preposition"]),
        ("The new policy is consonant ___ the agency's mandate to improve public service delivery.", ["to","with","in","for"], "with", "'Consonant with' means in harmony with or consistent with.", ["consonant with","formal adjective"]),
        ("The committee is incumbent ___ to act on the complaint within the prescribed period.", ["with","upon","to","for"], "upon", "'Incumbent upon' means obligatory for. (Note: 'It is incumbent upon the committee to act' is the full construction.)", ["incumbent upon","formal obligation"]),
        ("The employee was deprived ___ his right to due process.", ["from","of","with","to"], "of", "'Deprived of' means denied or stripped of.", ["deprived of","verb + preposition"]),
        ("The regulation is ancillary ___ the main policy on employee conduct.", ["for","to","with","of"], "to", "'Ancillary to' means supplementary to or subordinate to.", ["ancillary to","adjective + preposition"]),
    ]

    hard_questions += [
        ("The director is loath ___ admit that the project has failed.", ["in","to","for","of"], "to", "'Loath to' means reluctant to.", ["loath to","adjective + preposition"]),
        ("The committee is apprised ___ all developments in the case.", ["about","of","with","on"], "of", "'Apprised of' means informed of.", ["apprised of","formal verb"]),
        ("The employee was inured ___ the hardships of fieldwork after years of service.", ["with","to","from","by"], "to", "'Inured to' means accustomed to (something unpleasant).", ["inured to","adjective + preposition"]),
        ("The regulation is germane ___ the issue being discussed.", ["for","to","with","about"], "to", "'Germane to' means relevant to.", ["germane to","adjective + preposition"]),
        ("The supervisor was remiss ___ not informing the employees about the schedule change.", ["for","in","of","about"], "in", "'Remiss in' not doing something (negligent in).", ["remiss in","adjective + preposition"]),
        ("The committee is amenable ___ compromise on non-essential provisions.", ["for","to","with","about"], "to", "'Amenable to' means open to or willing to accept.", ["amenable to","adjective + preposition"]),
        ("The employee was imputed ___ having falsified his daily time record.", ["of","with","for","to"], "with", "'Imputed with' means accused of or attributed with (in Philippine legal usage).", ["imputed with","Philippine legal usage"]),
        ("The regulation is coterminous ___ the term of the appointing authority.", ["to","with","as","for"], "with", "'Coterminous with' means having the same boundaries or duration as.", ["coterminous with","formal expression"]),
        ("The director is abreast ___ the latest developments in the case.", ["with","of","about","on"], "of", "'Abreast of' means up to date with.", ["abreast of","adjective + preposition"]),
        ("The employee was adept ___ handling difficult clients.", ["in","at","with","for"], "at", "'Adept at' means skilled at.", ["adept at","adjective + preposition"]),
    ]

    hard_questions += [
        ("The committee is seized ___ jurisdiction over the complaint.", ["with","of","by","in"], "of", "'Seized of jurisdiction' (legal) means having taken cognizance of.", ["seized of","legal jurisdiction"]),
        ("The regulation is repugnant ___ the constitutional guarantee of equal protection.", ["with","to","against","for"], "to", "'Repugnant to' means contrary to or inconsistent with.", ["repugnant to","legal expression"]),
        ("The employee was constrained ___ file the complaint due to the persistent harassment.", ["in","to","for","from"], "to", "'Constrained to' means compelled to or forced to.", ["constrained to","formal verb"]),
        ("The supervisor is conversant ___ the intricacies of the procurement process.", ["about","with","in","of"], "with", "'Conversant with' means thoroughly familiar with.", ["conversant with","adjective + preposition"]),
        ("The committee is mandated ___ law to act on complaints within sixty days.", ["under","by","with","from"], "by", "'Mandated by law' means required by law.", ["mandated by","legal expression"]),
        ("The employee was inveigled ___ signing the document without reading it.", ["to","into","for","with"], "into", "'Inveigled into' means tricked or persuaded into.", ["inveigled into","verb + preposition"]),
        ("The regulation is antithetical ___ the principles of transparency and accountability.", ["with","to","for","against"], "to", "'Antithetical to' means directly opposed to.", ["antithetical to","adjective + preposition"]),
        ("The director is beholden ___ no one for his appointment to the position.", ["with","to","for","by"], "to", "'Beholden to' means indebted to or obligated to.", ["beholden to","adjective + preposition"]),
        ("The employee was mulcted ___ a fine equivalent to one month's salary.", ["with","of","by","for"], "of", "'Mulcted of' means penalized by having something taken away.", ["mulcted of","formal/legal verb"]),
        ("The committee is enjoined ___ acting on the matter pending resolution of the preliminary issue.", ["against","from","to","of"], "from", "'Enjoined from' means prohibited from or restrained from.", ["enjoined from","legal prohibition"]),
    ]

    for i, (question, choices, answer, explanation, tags) in enumerate(hard_questions):
        new.append(q(start_id + i, "Hard", st, question, choices, answer, explanation, tags))

    existing.extend(new)
    save("prepositions", existing)
    return len(new)


