# ARTICLES — needs +23 Easy, +6 Medium, +71 Hard
# ============================================================
def gen_articles():
    """Generate additional questions for Articles."""
    existing = load_existing("articles")
    start_id = max(item["id"] for item in existing) + 1
    new = []
    st = "Articles"

