        ("Identify the dangling modifier: 'Aware of the risks involved, extra precautions were taken during the operation.'", ["Aware of the risks involved, the team took extra precautions during the operation.","Extra precautions were taken because the team was aware of the risks involved.","Both A and B correctly fix the error.","The sentence is already correct."], "Both A and B correctly fix the error.", "'Aware of the risks' must modify a person/team, not 'extra precautions.'", ["dangling modifier","adjective phrase"]),
        ("Identify the dangling modifier: 'Confident of a favorable outcome, the appeal was filed before the deadline.'", ["Confident of a favorable outcome, the respondent filed the appeal before the deadline.","The appeal was filed before the deadline by the respondent, who was confident of a favorable outcome.","Both A and B correctly fix the error.","The sentence is already correct."], "Both A and B correctly fix the error.", "'Confident of a favorable outcome' must modify a person (the respondent), not 'the appeal.'", ["dangling modifier","adjective phrase"]),
        ("Identify the dangling modifier: 'Pressed for time, the quality of the output suffered as a result.'", ["Pressed for time, the employees produced lower-quality output.","The quality of the output suffered because the employees were pressed for time.","Both A and B correctly fix the error.","The sentence is already correct."], "Both A and B correctly fix the error.", "'Pressed for time' must modify people (employees), not 'the quality.'", ["dangling modifier","past participle"]),
        ("Identify the dangling modifier: 'Lacking the necessary qualifications, the application was denied by the screening committee.'", ["Lacking the necessary qualifications, the applicant had his application denied.","The application was denied because the applicant lacked the necessary qualifications.","Both A and B correctly fix the error.","The sentence is already correct."], "Both A and B correctly fix the error.", "'Lacking the necessary qualifications' must modify a person (the applicant), not 'the application.'", ["dangling modifier","present participle"]),
        ("Choose the sentence with CORRECT modifier placement:", ["The employees have already been notified about the schedule change.","The employees already have been notified about the schedule change.","Already the employees have been notified about the schedule change.","The employees have been already notified about the schedule change."], "The employees have already been notified about the schedule change.", "'Already' is correctly placed after the first auxiliary verb.", ["adverb placement","mid-position"]),
        ("Identify the dangling modifier: 'Committed to public service, the community benefited from the official's programs.'", ["Committed to public service, the official implemented programs that benefited the community.","The community benefited from the programs of the official, who was committed to public service.","Both A and B correctly fix the error.","The sentence is already correct."], "Both A and B correctly fix the error.", "'Committed to public service' must modify the official (who is committed), not 'the community.'", ["dangling modifier","past participle"]),
        ("Identify the dangling modifier: 'Surprised by the audit results, immediate corrective action was taken.'", ["Surprised by the audit results, the management took immediate corrective action.","Immediate corrective action was taken after the management was surprised by the audit results.","Both A and B correctly fix the error.","The sentence is already correct."], "Both A and B correctly fix the error.", "'Surprised by the audit results' must modify a person/group (management), not 'corrective action.'", ["dangling modifier","past participle"]),
        ("Identify the dangling modifier: 'Frustrated by the bureaucratic process, the application was withdrawn.'", ["Frustrated by the bureaucratic process, the applicant withdrew the application.","The application was withdrawn because the applicant was frustrated by the bureaucratic process.","Both A and B correctly fix the error.","The sentence is already correct."], "Both A and B correctly fix the error.", "'Frustrated by the bureaucratic process' must modify a person (the applicant), not 'the application.'", ["dangling modifier","adjective phrase"]),
        ("Identify the squinting modifier: 'The employees who completed the training successfully passed the evaluation.'", ["The employees who successfully completed the training passed the evaluation.","The employees who completed the training passed the evaluation successfully.","Both A and B are valid interpretations.","The sentence is clear as written."], "Both A and B are valid interpretations.", "'Successfully' could modify 'completed the training' (finished it well) or 'passed the evaluation' (passed it well).", ["squinting modifier","adverb ambiguity"]),
